import uuid as uuid_lib

from lib.db import db


class ActivityLike:
  """Like or unlike one activity for the signed-in user (backlog #18)."""

  @staticmethod
  def run(cognito_user_id, activity_uuid, like=True):
    model = {
      'errors': None,
      'data': None
    }

    if cognito_user_id is None or len(cognito_user_id) < 1:
      model['errors'] = ['cognito_user_id_blank']
      return model

    # Same target checks as CreateReply: the route maps these to 400 / 404.
    try:
      uuid_lib.UUID(str(activity_uuid))
    except ValueError:
      model['errors'] = ['invalid_activity_uuid']
      return model

    sql = db.template('activities', 'exists')
    if not db.query_value(sql, {'activity_uuid': activity_uuid}):
      model['errors'] = ['activity_not_found']
      return model

    # like.sql / unlike.sql change the likes row and likes_count in one
    # statement and return the new count. query_commit returns None on a
    # failed write AND when the caller has no users row (the SQL returns
    # NULL). 0 is a valid count after an unlike, so test for None, not
    # falsiness.
    sql = db.template('activities', 'like' if like else 'unlike')
    likes_count = db.query_commit(sql, {
      'cognito_user_id': cognito_user_id,
      'activity_uuid': activity_uuid
    })
    if likes_count is None:
      model['errors'] = ['like_not_saved']
      return model

    model['data'] = {
      'uuid': activity_uuid,
      'likes_count': likes_count,
      'liked': like
    }
    return model

from lib.db import db

# Likes (backlog #18). Creates the likes table. activities.likes_count already
# exists and is 0 everywhere, so there is nothing to backfill. Folded into
# schema.sql with the stamp bumped to this prefix.
class CreateLikesMigration:
  def migrate_sql():
    data = """
    CREATE TABLE IF NOT EXISTS public.likes (
      user_uuid UUID NOT NULL REFERENCES public.users(uuid) ON DELETE CASCADE,
      activity_uuid UUID NOT NULL REFERENCES public.activities(uuid) ON DELETE CASCADE,
      created_at TIMESTAMP default current_timestamp NOT NULL,
      PRIMARY KEY (user_uuid, activity_uuid)
    );
    """
    return data

  def rollback_sql():
    data = """
    DROP TABLE IF EXISTS public.likes;
    UPDATE public.activities SET likes_count = 0;
    """
    return data

  def migrate():
    db.query_commit(CreateLikesMigration.migrate_sql(), {})

  def rollback():
    db.query_commit(CreateLikesMigration.rollback_sql(), {})

/* Liked heart (backlog #18): solid heart (heart-filled.svg) in the app's
   theme purple, rgb(149,0,255), the same as the Crud button and avatar
   circles. These selectors are more specific than the generic rules in
   ActivityItem.css (.activity_item .activity_actions .icon and
   .action .counter), so they win regardless of which file loads last. */
.activity_item .activity_actions .activity_action_heart.liked .icon {
  fill: rgb(149,0,255);
}

.activity_item .activity_actions .activity_action_heart.liked .counter {
  color: rgb(149,0,255);
}
